      const slow = await buildCatalog(cfg({ endpoint: `${silent.url}/v1` }), { timeoutMs: 300 });
      assert.ok(Date.now() - timed < 3000, "the timeout ends the wait");
      assert.equal(slow.providers.find((p) => p.id === "session")!.status, "error");

